WITH exploded AS (SELECT id, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) e AS element), scored AS (SELECT *, PERCENT_RANK() OVER (ORDER BY element) AS element_percent_rank, DENSE_RANK() OVER (ORDER BY element NULLS FIRST) AS element_dense_rank FROM exploded), scored_price_tiers AS (SELECT *, DENSE_RANK() OVER (ORDER BY element DESC NULLS FIRST) AS element_dense_rank_2, RANK() OVER (ORDER BY element NULLS FIRST) AS element_rank FROM scored) SELECT id, element, element_percent_rank, element_dense_rank, element_dense_rank_2, element_rank, DENSE_RANK() OVER (ORDER BY element_rank NULLS FIRST) AS element_rank_dense_rank, PERCENT_RANK() OVER (ORDER BY element_percent_rank DESC NULLS FIRST) AS element_percent_rank_percent_rank, CUME_DIST() OVER w_running AS element_rank_cume_dist FROM scored_price_tiers WINDOW w_running AS (ORDER BY element_rank DESC NULLS FIRST)
